Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
This is an easier version of the problem. In this version, $$$n \le 6$$$.Marek is working hard on creating strong testcases to his new algorithmic problem. You want to know what it is? Nah, we're not telling you. However, we can tell you how he generates the testcases.Marek chooses an integer $$$n$$$ and $$$n^2$$$ integers $$$p_{ij}$$$ ($$$1 \le i \le n$$$, $$$1 \le j \le n$$$). He then generates a random bipartite graph with $$$2n$$$ vertices. There are $$$n$$$ vertices on the left side: $$$\ell_1, \ell_2, \dots, \ell_n$$$, and $$$n$$$ vertices on the right side: $$$r_1, r_2, \dots, r_n$$$. For each $$$i$$$ and $$$j$$$, he puts an edge between vertices $$$\ell_i$$$ and $$$r_j$$$ with probability $$$p_{ij}$$$ percent.It turns out that the tests will be strong only if a perfect matching exists in the generated graph. What is the probability that this will occur?It can be shown that this value can be represented as $$$\frac{P}{Q}$$$ where $$$P$$$ and $$$Q$$$ are coprime integers and $$$Q \not\equiv 0 \pmod{10^9+7}$$$. Let $$$Q^{-1}$$$ be an integer for which $$$Q \cdot Q^{-1} \equiv 1 \pmod{10^9+7}$$$. Print the value of $$$P \cdot Q^{-1}$$$ modulo $$$10^9+7$$$.
</problem_description>

Here is the GNU C++17 code you have to repair:
<original_code>
// 16
// I remember reading the editorial...
// should've already solved this by now.

#ifndef LOCAL
#define NDEBUG 1
#endif
#include<bits/stdc++.h>
#include<Modular.h>

using modular=Modular<1000000007>;

int main(){
	std::ios::sync_with_stdio(0);std::cin.tie(0);
	int number; std::cin>>number;
	//std::vector<std::vector<modular>> probability(number, std::vector<modular>(number));
	std::vector<modular> probability(number*number);
	//for(auto& row: probability)
	for(auto& value: probability){
		int percentage; std::cin>>percentage;
		value=modular(1)/100*percentage;
	}

	std::vector<modular> total;

	int const middle=number/2;
	auto const maskValue=[&]{
		std::array<int, 1<<6> maskValue;
		assert(number<=6);
		int count=0;
		for(int matchMask=0; matchMask<(int)maskValue.size(); ++matchMask){
			maskValue[matchMask]=__builtin_popcount(matchMask)==middle ? count++: -1;
		}
		total.resize(1<<count);
		return maskValue;
	}();

	auto const process=[&](int left, int right, auto handle){
		auto const len=right-left;
		for(int edgeMask=0; edgeMask<(1<<(len*number)); ++edgeMask){
			modular totalProbability=1;

			// inefficient
			for(int tmp=edgeMask, i=left*number; i<right*number; ++i, tmp>>=1){
				totalProbability*=tmp&1 ?  probability[i]: 1-probability[i];
				if(totalProbability==0) goto continue_outer_2;
			}

			{ // compute matchSets and call handle
				// even more inefficient...?
				std::array<char, 3> data{};
				assert(len<=(int)data.size());
				int matchSets{};
				while(true){
					// process data
					int matchMask{};
					for(int index=0; index<len; ++index){
						if(not(edgeMask>>(index*number+data[index])&1)) goto continue_outer;
						if(matchMask&1<<data[index]) goto continue_outer;
						matchMask|=1<<data[index];
					}
					if(right==number) // second half, should invert
						matchMask^=(1<<number)-1;

					matchSets|=1<<maskValue[matchMask];

continue_outer:
					// increase data
					for(int i=len-1;;){
						if(i<0) goto break_outer;
						if(data[i]==number-1){data[i]=0; --i;}
						else{++data[i]; break;}
					}
				}
break_outer:;

				handle(matchSets, totalProbability);
			}

continue_outer_2:;
		}
	};
	assert(middle<number);
	process(0, middle,[&](int sets, modular probability){
		total[sets]+=probability;
	});
	for(int dim=1; dim<(int)total.size(); dim<<=1)
		for(int i=0; i<(int)total.size(); ++i)
			if(not(i&dim))
				total[i|dim]+=total[i];

	modular result{};
	process(middle, number,[&](int sets, modular probability){
		result+=probability*(total.back()-total[(1<<number)-1-sets]);
	});
	std::cout<<(int)result<<'\n';

}

